1	/* ----------------------------------------------------------------------------
2	Copyright (c) 2019-2026, Microsoft Research, Daan Leijen
3	This is free software; you can redistribute it and/or modify it under the
4	terms of the MIT license. A copy of the license can be found in the file
5	"LICENSE" at the root of this distribution.
6	-----------------------------------------------------------------------------*/
7	
8	/* ----------------------------------------------------------------------------
9	  Implement dynamic thread local variables (used by heap's for their theap's).
10	  Unlike most OS native implementations there is no limit on the number
11	  that can be allocated.
12	-----------------------------------------------------------------------------*/
13	
14	#include "mimalloc.h"
15	#include "mimalloc/internal.h"
16	#include "mimalloc/prim.h"
17	
18	/* -----------------------------------------------------------
19	  Each thread can have (a dynamically expanding) array of
20	  thread-local values. Each slot has a value and a version.
21	  The version is used to safely reuse slots.
22	----------------------------------------------------------- */
23	typedef struct mi_tls_slot_s {
24	  size_t  version;
25	  void*   value;
26	} mi_tls_slot_t;
27	
28	typedef struct mi_thread_locals_s {
29	  size_t        count;
30	  mi_memid_t    memid;
31	  mi_tls_slot_t slots[1];
32	} mi_thread_locals_t;
33	
34	static mi_thread_locals_t mi_thread_locals_empty = mi_init_struct_zero;
35	
36	
37	/* -----------------------------------------------------------
38	  We have 2 thread local variable which we implement with either
39	  a C thread local declaration or using pthread keys.
40	  - mi_thread_locals: points to an array of thread locals for most keys
41	  - mi_slot_fast: a single dedicated thread local for slightly faster access. (used for the main heap's theap)
42	----------------------------------------------------------- */
43	
44	#if MI_TLS_MODEL_PTHREADS || defined(__APPLE__)   // macOS has fast pthreads
45	// Use pthreads
46	#define mi_define_thread_local(tp,name,initval) \
47	  static pthread_key_t __##name##_key = MI_PTHREAD_KEY_INVALID; \
48	  static inline tp   name##_peek(void)    { return (tp)mi_pthread_key_get(__##name##_key); } \
49	  static inline tp   name##_get(void)     { tp result = name##_peek(); return (result!=NULL ? result : initval); } \
50	  static inline bool name##_set(tp val)   { return mi_pthread_key_set(&__##name##_key,val); } \
51	  static inline void name##_delete(void)  { mi_pthread_key_delete(&__##name##_key); }
52	
53	#else
54	// Direct thread locals
55	#define mi_define_thread_local(tp,name,initval) \
56	  static mi_decl_thread tp __##name = initval; \
57	  static inline tp   name##_peek(void)    { return __##name; } \
58	  static inline tp   name##_get(void)     { tp result = __##name; return (result!=NULL ? result : initval); } \
59	  static inline bool name##_set(tp val)   { __##name = val; return true; } \
60	  static inline void name##_delete(void)  {  }
61	#endif
62	
63	mi_define_thread_local(mi_thread_locals_t*, mi_thread_locals, &mi_thread_locals_empty)
64	mi_define_thread_local(void*, mi_slot_fast, NULL)
65	
66	
67	/* -----------------------------------------------------------
68	  Each key consists of the slot index in the lower bits,
69	  and its version it the top bits. When we get a value
70	  the version must match or we return NULL. When we set
71	  a value, we also set the version of the key.
72	----------------------------------------------------------- */
73	
74	#if MI_SIZE_BITS >= 64
75	#define MI_TLS_IDX_BITS     (MI_SIZE_BITS/4)      /* 16 bits for the index, 48 bits for the version */
76	#elif MI_SIZE_BITS >= 32
77	#define MI_TLS_IDX_BITS     (12)                  /* 12 bits for index, 20 for the version? */
78	#else
79	#error not enough bits for the version for thread locals
80	#endif
81	#define MI_TLS_IDX_MASK     ((MI_ZU(1)<<MI_TLS_IDX_BITS)-1)
82	#define MI_TLS_IDX_MAX      MI_TLS_IDX_MASK
83	#define MI_TLS_VERSION_MAX  ((MI_ZU(1)<<(MI_SIZE_BITS - MI_TLS_IDX_BITS))-1)
84	
85	
86	static size_t mi_key_index( size_t key ) {
87	  return (key & MI_TLS_IDX_MASK);
88	}
89	
90	static size_t mi_key_version( size_t key ) {
91	  return (key >> MI_TLS_IDX_BITS);
92	}
93	
94	static mi_thread_local_t mi_key_create( size_t index, size_t version ) {
95	  mi_assert_internal(version != 0 && version <= MI_TLS_VERSION_MAX);
96	  mi_assert_internal(index <= MI_TLS_IDX_MAX);
97	  const mi_thread_local_t key = ((version << MI_TLS_IDX_BITS) | index);
98	  mi_assert_internal(key != 0);
99	  return key;
100	}
101	
102	
103	// dynamically reallocate the thread local slots when needed
104	static mi_thread_locals_t* mi_thread_locals_expand(size_t least_idx) {
105	  mi_thread_locals_t* tls_old = mi_thread_locals_get();
106	  const size_t count_old = tls_old->count;
107	  size_t count;
108	  if (count_old==0) {
109	    tls_old = NULL; // so we allocate fresh from mi_thread_locals_empty
110	    count = 16;     // start with 16 slots
111	  }
112	  else if (count_old >= 1024) {
113	    count = count_old + 1024;  // at some point increase linearly
114	  }
115	  else {
116	    count = 2*count_old;       // and double initially
117	  }
118	  if (count <= least_idx) {
119	    count = least_idx + 1;
120	  }
121	  if (count > MI_TLS_IDX_MAX) { return NULL; }  // too large
122	  // allocate as meta (for secure mode)
123	  // we could also allocate on the main heap; this is recursion safe as that uses the fast local key
124	  mi_memid_t memid = (tls_old==NULL ? _mi_memid_none() : tls_old->memid);
125	  mi_thread_locals_t* tls = (mi_thread_locals_t*)_mi_meta_rezalloc(_mi_subproc(), tls_old, sizeof(mi_thread_locals_t) + count*sizeof(mi_tls_slot_t), &memid);
126	  if mi_unlikely(tls==NULL) return NULL;
127	  tls->memid = memid;
128	  tls->count = count;
129	  mi_thread_locals_set(tls);
130	  return tls;
131	}
132	
133	static mi_decl_noinline bool mi_thread_local_set_expand( mi_thread_local_t key, void* val ) {
134	  if (val==NULL) return true;
135	  const size_t idx = mi_key_index(key);
136	  mi_thread_locals_t* tls = mi_thread_locals_expand(idx);
137	  if (tls==NULL) {
138	    _mi_error_message(EFAULT,"unable to allocate thread local variables\n");
139	    return false;
140	  }
141	  mi_assert_internal(tls == mi_thread_locals_get());
142	  mi_assert_internal(idx < tls->count);
143	  tls->slots[idx].value = val;
144	  tls->slots[idx].version = mi_key_version(key);
145	  return true;
146	}
147	
148	// set a tls slot; returns `true` if successful.
149	// Can return `false` if we could not reallocate the slots array.
150	static mi_decl_noinline bool mi_thread_local_set_regular( mi_thread_local_t key, void* val ) {
151	  mi_thread_locals_t* tls = mi_thread_locals_get();
152	  mi_assert_internal(tls!=NULL);
153	  mi_assert_internal(key!=0);
154	  const size_t idx = mi_key_index(key);
155	  if mi_likely(idx < tls->count) {
156	    tls->slots[idx].value = val;
157	    tls->slots[idx].version = mi_key_version(key);
158	    return true;
159	  }
160	  else {
161	    return mi_thread_local_set_expand( key, val );  // tailcall
162	  }
163	}
164	
165	bool _mi_thread_local_set( mi_thread_local_t key, void* val ) {
166	  mi_assert_internal(key!=0);
167	  if (key == mi_thread_local_key_fast) {
168	    return mi_slot_fast_set(val);
169	  }
170	  else {
171	    return mi_thread_local_set_regular(key,val);
172	  }
173	}
174	
175	// get a tls slot value
176	static mi_decl_noinline void* mi_thread_local_get_regular( mi_thread_local_t key ) {
177	  mi_assert_internal(key!=0);
178	  const mi_thread_locals_t* const tls = mi_thread_locals_peek();
179	  if mi_unlikely(tls==NULL) {
180	    // this can happen if a thread local is accessed after the thread local has been freed
181	    // from mi_thread_done or mi_process_done.
182	    // todo: can we remove this check? now we can still call this from process done when stats are printed (which calls mi_heap_theap_peek)
183	    return NULL;
184	  }
185	  const size_t idx = mi_key_index(key);
186	  if mi_likely(idx < tls->count && mi_key_version(key) == tls->slots[idx].version) {
187	    return tls->slots[idx].value;
188	  }
189	  else {
190	    return NULL;
191	  }
192	}
193	
194	// get a thread local value
195	void* _mi_thread_local_get( mi_thread_local_t key ) {
196	  mi_assert_internal(key!=0);
197	  if mi_likely(key == mi_thread_local_key_fast) {
198	    return mi_slot_fast_get();
199	  }
200	  else {
201	    return mi_thread_local_get_regular(key);
202	  }
203	}
204	
205	void _mi_thread_locals_thread_done(void) {
206	  mi_thread_locals_t* const tls = mi_thread_locals_peek();
207	  if (tls!=NULL && tls->count > 0) {
208	    _mi_meta_free(_mi_subproc(), tls, tls->memid);
209	    mi_thread_locals_set(NULL);
210	  }
211	  if (mi_slot_fast_peek() != NULL) {
212	    mi_slot_fast_set(NULL);
213	  }
214	}
215	
216	/* -----------------------------------------------------------
217	Create and free fresh TLS key's
218	----------------------------------------------------------- */
219	#include "bitmap.h"
220	
221	static mi_lock_t    mi_thread_locals_lock;    // we need a lock in order to re-allocate the slot bits
222	static mi_bitmap_t* mi_thread_locals_free;    // reuse an arena bitmap to track which slots were assigned (1=free, 0=in-use)
223	static mi_memid_t   mi_thread_locals_memid;   // provenance of mi_thread_locals_free
224	static size_t       mi_thread_locals_version; // version to be able to reuse slots safely
225	
226	void _mi_thread_locals_init(void) {
227	  mi_lock_init(&mi_thread_locals_lock);
228	}
229	
230	void _mi_thread_locals_done(void) {
231	  mi_lock(&mi_thread_locals_lock) {
232	    mi_bitmap_t* const slots = mi_thread_locals_free;
233	    if (slots!=NULL) {
234	      _mi_meta_free(_mi_subproc_main(), slots, mi_thread_locals_memid);
235	    }
236	  }
237	  mi_lock_done(&mi_thread_locals_lock);
238	  mi_thread_locals_delete();
239	  mi_slot_fast_delete();
240	}
241	
242	// strange signature but allows us to reuse the arena code for claiming free pages
243	static bool mi_thread_local_claim_fun(size_t _slice_index, mi_arena_t* _arena, bool* keep_set) {
244	  MI_UNUSED(_slice_index); MI_UNUSED(_arena);
245	  *keep_set = false;
246	  return true;
247	}
248	
249	// When we claim a free slot, we increase the global version counter
250	// (so if we reuse a slot it will be returning NULL initially when a thread tries to get it)
251	static mi_thread_local_t mi_thread_local_claim(void) {
252	  size_t idx = 0;
253	  if (mi_thread_locals_free != NULL && mi_bitmap_try_find_and_claim(mi_thread_locals_free,0,&idx,&mi_thread_local_claim_fun,NULL)) {
254	    mi_thread_locals_version++;
255	    if (mi_thread_locals_version >= MI_TLS_VERSION_MAX) { mi_thread_locals_version = 1; }  /* wrap around the version */
256	    return mi_key_create( idx, mi_thread_locals_version);
257	  }
258	  else {
259	    return 0;
260	  }
261	}
262	
263	static bool mi_thread_local_create_expand(void) {
264	  mi_bitmap_t* const slots = mi_thread_locals_free;
265	  // 1024 bits at a time
266	  const size_t oldcount = (slots==NULL ? 0 : mi_bitmap_max_bits(slots));
267	  const size_t newcount = 1024 + oldcount;
268	  if (newcount > MI_TLS_IDX_MAX) { return false; }
269	  const size_t newsize = mi_bitmap_size( newcount, NULL );
270	  // mi_bitmap_t* newslots = (mi_bitmap_t*)mi_zalloc_aligned(newsize, MI_BCHUNK_SIZE);
271	  mi_memid_t memid;
272	  mi_bitmap_t* newslots = (mi_bitmap_t*)_mi_meta_zalloc_aligned(_mi_subproc_main(), newsize, MI_BCHUNK_SIZE, &memid); // always allocate thread locals in the main subprocess
273	  mi_assert_internal(_mi_is_aligned(newslots,MI_BCHUNK_SIZE));
274	  if (newslots==NULL) { return false; }
275	  if (slots!=NULL) {
276	    // copy over the previous bitmap
277	    const size_t oldsize = mi_bitmap_size(oldcount,NULL);
278	    _mi_memcpy_aligned(newslots, slots, oldsize);
279	    _mi_meta_free(_mi_subproc_main(), slots, mi_thread_locals_memid);
280	  }
281	  mi_bitmap_init(newslots, newcount, true /* pretend already zero'd so we do not zero out the copied old entries */);
282	  mi_bitmap_unsafe_setN(newslots, oldcount, newcount - oldcount);  /* set the new expanded slots as available */
283	  mi_thread_locals_free = newslots;
284	  mi_thread_locals_memid = memid;
285	  return true;
286	}
287	
288	
289	// create a fresh key
290	mi_thread_local_t _mi_thread_local_create(void) {
291	  mi_thread_local_t key = 0;
292	  mi_lock(&mi_thread_locals_lock) {
293	    key = mi_thread_local_claim();
294	    if (key==0) {
295	      if (mi_thread_local_create_expand()) {
296	        key = mi_thread_local_claim();
297	      }
298	    }
299	  }
300	  mi_assert_internal(key!=0);
301	  mi_assert_internal(key!=mi_thread_local_key_fast);
302	  return key;
303	}
304	
305	// free a key
306	void _mi_thread_local_free(mi_thread_local_t key) {
307	  if (key==0) return;
308	  const size_t idx = mi_key_index(key);
309	  mi_lock(&mi_thread_locals_lock) {
310	    mi_bitmap_t* const slots = mi_thread_locals_free;
311	    if (slots!=NULL && idx < mi_bitmap_max_bits(slots)) {
312	      mi_bitmap_set(slots,idx);
313	    }
314	  }
315	}
