364	  #else
365	    #error define the TLS model fixed slots (or change the TLS model away from MI_TLS_MODEL_FIXED)
366	  #endif
367	#endif
368	
369	static inline mi_theap_t* _mi_theap_default(void) {
370	  return (mi_theap_t*)mi_prim_tls_slot(MI_TLS_MODEL_FIXED_DEFAULT);
371	}
