373	static inline mi_theap_t* _mi_theap_cached(void) {
374	  return (mi_theap_t*)mi_prim_tls_slot(MI_TLS_MODEL_FIXED_CACHED);
375	}
376	
377	#else
378	#error "no TLS model is defined for this platform?"
379	#endif
