385	}
386	
387	// Get (and possible create) the theap belonging to a heap
388	// We cache the last accessed theap in `_mi_theap_cached` for better performance.
389	static inline mi_theap_t* _mi_heap_theap(mi_heap_t* heap) {
390	  mi_theap_t* theap = _mi_theap_cached();
391	  #if MI_THEAP_INITASNULL
392	  if mi_likely(theap!=NULL && _mi_theap_heap_peek(theap)==heap) return theap;
393	  #else
394	  if mi_likely(_mi_theap_heap_peek(theap)==heap) return theap;
395	  #endif
396	  return _mi_heap_theap_get_or_init(heap);
397	}
398	
399	// Get the theap belonging to a heap without creating it if it is not yet initialized.
400	static inline mi_theap_t* _mi_heap_theap_peek(const mi_heap_t* heap) {
401	  mi_theap_t* theap = _mi_theap_cached();
402	  #if MI_THEAP_INITASNULL
403	  if mi_likely(theap!=NULL && _mi_theap_heap_peek(theap)==heap) return theap;
404	  #else
405	  if mi_likely(_mi_theap_heap_peek(theap)==heap) return theap;
406	  #endif
407	  theap = (mi_theap_t*)_mi_thread_local_get(heap->theap);  // don't update the cache on a query
408	  mi_assert_internal(theap==NULL || (!_mi_is_empty_theap(theap) && theap->heap==heap));
409	  return theap;
410	}
411	
412	// Find the associated theap or NULL if it does not exist (during shutdown)
413	// Should be fast as it is called in `free.c:mi_free_try_collect`.
414	static inline mi_theap_t* _mi_page_associated_theap_peek(mi_page_t* page) {
415	  mi_heap_t* const heap = mi_page_heap(page);
416	  mi_theap_t* const theap = (mi_theap_t*)_mi_thread_local_get(heap->theap);
417	  if (theap==NULL) return NULL;
418	  if (theap->heap != heap) return NULL; // should never happen, but can happen for a free across subprocesses, which can happen during pthread tls storage deallocation
419	  mi_assert_internal(!_mi_is_empty_theap(theap) && mi_theap_matches_thread(theap));
420	  // note: for pages allocated by a detached theap, the returned theap may not be detached
421	  return theap;
422	}
423	
424	#endif  // MI_PRIM_TLS_H
425

