66	static bool mi_theap_is_valid(mi_theap_t* theap) {
67	  mi_assert_internal(theap!=NULL);
68	  mi_heap_t* const heap = _mi_theap_heap_peek(theap);
69	  mi_assert_internal(heap != NULL);
70	  mi_theap_t* const heap_theap = _mi_heap_theap_peek(heap);  // don't use mi_heap_theap as that may re-initialize the thread
71	  mi_assert_internal(heap_theap==NULL || heap_theap == theap);
72	  mi_theap_visit_pages(theap, &mi_theap_page_is_valid, true, NULL, NULL);
73	  for (size_t bin = 0; bin < MI_BIN_COUNT; bin++) {
74	    mi_assert_internal(_mi_page_queue_is_valid(theap, &theap->pages[bin]));
75	  }
76	  return true;
77	}
