158	void mi_collect(bool force) mi_attr_noexcept {
159	  // cannot really collect process wide, just a theap..
160	  mi_theap_collect(_mi_theap_default(), force);
161	}
162	
163	void mi_heap_collect(mi_heap_t* heap, bool force) {
164	  // cannot really collect a heap, just a theap..
165	  mi_theap_collect(mi_heap_theap(heap), force);
166	}
