308	mi_theap_t* _mi_theap_alloc(mi_heap_t* heap, mi_tld_t* tld) {
309	  mi_assert_internal(tld!=NULL);
310	  mi_assert_internal(heap!=NULL);
311	  mi_assert_internal(tld->thread_id == MI_THREADID_DETACHED || _mi_thread_id() == tld->thread_id);
312	  // mi_assert_internal(_mi_heap_theap_peek(heap)==NULL);  // don't access thread locals as this is called on thread init
313	
314	  // allocate and initialize a theap
315	  mi_memid_t memid;
316	  mi_theap_t* theap;
317	  
318	  if (heap->exclusive_arena == NULL) {
319	    theap = (mi_theap_t*)_mi_meta_zalloc(heap->subproc, sizeof(mi_theap_t), &memid);
320	  }
321	  else {
322	    // theaps associated with a specific arena are allocated in that arena
323	    // note: takes up at least one slice which is quite wasteful...
324	    const size_t size = _mi_align_up(sizeof(mi_theap_t),MI_ARENA_MIN_OBJ_SIZE);
325	    theap = (mi_theap_t*)_mi_arenas_alloc(heap, size, true, true, heap->exclusive_arena, tld->thread_seq, tld->numa_node, &memid);    
326	  }
327	  if (theap==NULL) {
328	    _mi_error_message(ENOMEM, "unable to allocate theap meta-data\n");
329	    return NULL;
330	  }
331	
332	  theap->memid = memid;
333	  return theap;
334	}
