372	// Thread termination and heap delete/destroy might run concurrently 
373	// and we need to ensure we free the memory correctly. A heap or tld
374	// will first "detach" its theaps so it has a list with theaps that are
375	// no longer shared, and only then free's the theaps in that list.
376	// To detach we need to hold both the `heap->theaps_lock` and the `tld->theaps_lock`.
377	// Due to lock-inversion we need to use `mi_lock_try_acquire` and if that fails
378	// we back-off, release the outer lock, and try again until we succeed.
379	
380	// Remove the theaps in this heap from any thread local tld lists.
381	void _mi_heap_detach_theaps( mi_heap_t* heap ) {
382	  bool all_detached;
383	  do {
384	    all_detached = true;
385	    mi_lock(&heap->theaps_lock) {
386	      mi_theap_t* theap = heap->theaps;
387	      while (theap != NULL) {
388	        mi_theap_t* next = theap->hnext;
389	        mi_tld_t* tld = theap->tld; 
390	        if (tld != NULL) {
391	          if (mi_lock_try_acquire(&tld->theaps_lock)) {
392	            // remove the theap from the tld theaps list
393	            if (theap->tnext != NULL) { theap->tnext->tprev = theap->tprev;  }
394	            if (theap->tprev != NULL) { theap->tprev->tnext = theap->tnext;  }
395	                                else { mi_assert_internal(theap->tld->theaps == theap); theap->tld->theaps = theap->tnext; }
396	            theap->tnext = theap->tprev = NULL;       
397	            theap->tld = NULL;
398	            mi_lock_release(&tld->theaps_lock);
399	          }
400	          else {
401	            all_detached = false;
402	          }
403	        }
404	        theap = next;
405	      }
406	    }
407	    if (!all_detached) {
408	      mi_subproc_stat_counter_increase(heap->subproc,heaps_delete_wait,1);
409	      _mi_prim_thread_yield();
410	    }
411	  } while (!all_detached);
412	}
413	
414	// Remove the theaps in this thread from the heaps that own them.
415	void _mi_tld_detach_theaps( mi_tld_t* tld ) {
416	  bool all_detached;
417	  do {
418	    all_detached = true;
419	    mi_lock(&tld->theaps_lock) {
420	      mi_theap_t* theap = tld->theaps;
421	      while (theap != NULL) {
422	        mi_theap_t* next = theap->tnext;
423	        mi_assert_internal(theap->page_count==0);
424	        mi_heap_t* heap = _mi_theap_heap_peek(theap); // now the heap might be NULL from an earlier iteration
425	        if (heap != NULL) {
426	          if (mi_lock_try_acquire(&heap->theaps_lock)) {
427	            // merge stats into the owning heap stats
428	            _mi_stats_merge_into(&heap->stats, &theap->stats);
429	            // remove the theap from the heap list
430	            if (theap->hnext != NULL) { theap->hnext->hprev = theap->hprev; }
431	            if (theap->hprev != NULL) { theap->hprev->hnext = theap->hnext; }
432	                                else { mi_assert_internal(heap->theaps == theap); heap->theaps = theap->hnext; }
433	            theap->hnext = theap->hprev = NULL;
434	            // and set `heap` to NULL
435	            mi_atomic_store_ptr_release(mi_heap_t, &theap->heap, NULL);
436	            mi_lock_release(&heap->theaps_lock);
437	          }
438	          else {
439	            all_detached = false;
440	          }
441	        }
442	        theap = next;
443	      }
444	    }
445	    if (!all_detached) {
446	      mi_subproc_stat_counter_increase(tld->subproc,heaps_delete_wait,1);
447	      _mi_prim_thread_yield();
448	    }
449	  } while (!all_detached);
450	}
