mi_decl_hidden mi_decl_cache_align mi_theap_t _mi_theap_empty_wrong = mi_init_struct_zero;  // used for error paths
mi_decl_hidden bool _mi_process_is_initialized = false;  // set to `true` in `mi_process_init`.


